import{_ as a,o as n,c as p,ag as l}from"./chunks/framework.PVHj0As1.js";const i="/pub-blog/assets/image-20240829175251444.LjIkpZ5M.png",h="/pub-blog/assets/image-20240829173019521.DAA2Ubqs.png",e="/pub-blog/assets/image-20240829173614612.DSr2--5q.png",t="/pub-blog/assets/image-20240829174815936.BRQEw_mj.png",k="/pub-blog/assets/image-20240829175108921.C4q9dvb2.png",b=JSON.parse('{"title":"三文带你轻松上手鸿蒙的AI语音03-文本合成声音","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/三文带你轻松上手鸿蒙的AI语音/三文带你轻松上手鸿蒙的AI语音03-文本合成声音/03-文本合成声音.md","filePath":"鸿蒙开发技巧/三文带你轻松上手鸿蒙的AI语音/三文带你轻松上手鸿蒙的AI语音03-文本合成声音/03-文本合成声音.md","lastUpdated":1730788610000,"__rawMarkdown":"# 三文带你轻松上手鸿蒙的AI语音03-文本合成声音\\n\\n## 前言\\n\\n> 接上文  **三文带你轻松上手鸿蒙的AI语音02-声音文件转文本**\\n\\nHarmonyOS NEXT 提供的AI 文本合并语音功能，可以将一段不超过10000字符的文本合成为语音并进行播报。\\n\\n场景举例\\n\\n- 手机在无网状态下，系统应用无障碍（屏幕朗读）接入文本转语音能力，为视障人士提供播报能力。\\n- 类似微信读书，可以实现将文章内容通过语音朗读，可以在无法不方便阅读文章时提供帮助，如一边送外卖一边听书。\\n\\n## 实现效果\\n\\n![image-20240829175251444](%E4%B8%89%E6%96%87%E5%B8%A6%E4%BD%A0%E8%BD%BB%E6%9D%BE%E4%B8%8A%E6%89%8B%E9%B8%BF%E8%92%99%E7%9A%84AI%E8%AF%AD%E9%9F%B303-%E6%96%87%E6%9C%AC%E5%90%88%E6%88%90%E5%A3%B0%E9%9F%B3.assets/image-20240829175251444.png)\\n\\n## 使用流程\\n\\n1. 创建文本合成语音引擎\\n2. 设置监听回调\\n3. 开始合成\\n\\n![image-20240829173019521](%E4%B8%89%E6%96%87%E5%B8%A6%E4%BD%A0%E8%BD%BB%E6%9D%BE%E4%B8%8A%E6%89%8B%E9%B8%BF%E8%92%99%E7%9A%84AI%E8%AF%AD%E9%9F%B303-%E6%96%87%E6%9C%AC%E5%90%88%E6%88%90%E5%A3%B0%E9%9F%B3.assets/image-20240829173019521.png)\\n\\n\\n\\n## 创建文本合成语音引擎\\n\\n> 文末会提供封装后的代码\\n\\n创建文本合成语音引擎需要先引入  `textToSpeech`，然后调用其 `createEngine` 方法时，需要准备 初始化引擎的参数\\n\\n![image-20240829173614612](%E4%B8%89%E6%96%87%E5%B8%A6%E4%BD%A0%E8%BD%BB%E6%9D%BE%E4%B8%8A%E6%89%8B%E9%B8%BF%E8%92%99%E7%9A%84AI%E8%AF%AD%E9%9F%B303-%E6%96%87%E6%9C%AC%E5%90%88%E6%88%90%E5%A3%B0%E9%9F%B3.assets/image-20240829173614612.png)\\n\\n## 设置监听回调\\n\\n调用完`createEngine` 时会返回相应实例，此时可以设置监听回调。\\n\\n1. onStart 播报开始时回调\\n2. onStop 播报结束时回调\\n3. onComplete 合成或播报结束后分别回调此接口，返回请求ID，完成播报相关信息\\n4. onData 合成播报过程中回调此接口，返回请求ID，音频流信息，音频附加信息如格式、时长等。若需要返回音频流信息，请实现此接口。\\n5. onError 合成播报过程中，出现错误时回调，返回请求ID、错误码及错误描述。\\n\\n\\n\\n![image-20240829174815936](%E4%B8%89%E6%96%87%E5%B8%A6%E4%BD%A0%E8%BD%BB%E6%9D%BE%E4%B8%8A%E6%89%8B%E9%B8%BF%E8%92%99%E7%9A%84AI%E8%AF%AD%E9%9F%B303-%E6%96%87%E6%9C%AC%E5%90%88%E6%88%90%E5%A3%B0%E9%9F%B3.assets/image-20240829174815936.png)\\n\\n## 开始合成\\n\\n完成上面的实例创建和设置监听后，便可以调用 speak方法开始合成了。但是在调用speak时，也需要传递相应的参数。\\n\\n![image-20240829175108921](%E4%B8%89%E6%96%87%E5%B8%A6%E4%BD%A0%E8%BD%BB%E6%9D%BE%E4%B8%8A%E6%89%8B%E9%B8%BF%E8%92%99%E7%9A%84AI%E8%AF%AD%E9%9F%B303-%E6%96%87%E6%9C%AC%E5%90%88%E6%88%90%E5%A3%B0%E9%9F%B3.assets/image-20240829175108921.png)\\n\\n\\n\\n\\n\\n## 封装好的代码\\n\\n```typescript\\nimport { textToSpeech } from \'@kit.CoreSpeechKit\';\\n\\nclass TextToSpeechManager {\\n  /** 语音转文本引擎 */\\n  private ttsEngine: textToSpeech.TextToSpeechEngine | null = null\\n  /** 创建引擎的配置参数 */\\n  private static extraParam: Record<string, Object> =\\n    {\\n      // 风格 interaction-broadcast：广播风格\\n      \\"style\\": \'interaction-broadcast\',\\n      // 区域信息。 可选，不设置时默认为“CN”，当前仅支持“CN”。\\n      \\"locate\\": \'CN\',\\n      // 引擎名称。 可选，引擎名称，不设置是默认为空，当前仅支持单应用、单实例\\n      \\"name\\": \'EngineName\'\\n    }\\n  /** 创建引擎的配置参数 */\\n  private static initParamsInfo: textToSpeech.CreateEngineParams = {\\n    // 语种， 当前仅支持“zh-CN”中文。\\n    language: \'zh-CN\',\\n    // 音色。 0为聆小珊女声音色，当前仅支持聆小珊女声音色。\\n    person: 0,\\n    // 模式。 0为在线，目前不支持；1为离线，当前仅支持离线模式。\\n    online: 1,\\n    extraParams: TextToSpeechManager.extraParam\\n  }\\n  /** 会话ID，一个实例只能使用一次 */\\n  private requestId: string\\n\\n  constructor() {\\n    this.requestId = `tts` + Date.now()\\n  }\\n\\n  /** 创建引擎 */\\n  async createEngine() {\\n    return this.ttsEngine = await textToSpeech.createEngine(TextToSpeechManager.initParamsInfo)\\n  }\\n\\n  /** 设置回调监听 */\\n  async setListener(callback?: (res: textToSpeech.CompleteResponse) => void) {\\n    // 设置speak的回调信息\\n    let speakListener: textToSpeech.SpeakListener = {\\n      // 开始播报回调\\n      onStart(requestId: string, response: textToSpeech.StartResponse) {\\n        console.info(`onStart, requestId: ${requestId} response: ${JSON.stringify(response)}`);\\n      },\\n      // 合成完成及播报完成回调\\n      onComplete(requestId: string, response: textToSpeech.CompleteResponse) {\\n        console.info(`onComplete, requestId: ${requestId} response: ${JSON.stringify(response)}`);\\n        callback && callback(response)\\n      },\\n      // 停止播报回调\\n      onStop(requestId: string, response: textToSpeech.StopResponse) {\\n        console.info(`onStop, requestId: ${requestId} response: ${JSON.stringify(response)}`);\\n      },\\n      // 返回音频流\\n      onData(requestId: string, audio: ArrayBuffer, response: textToSpeech.SynthesisResponse) {\\n        console.info(`onData, requestId: ${requestId} sequence: ${JSON.stringify(response)} audio: ${JSON.stringify(audio)}`);\\n      },\\n      // 错误回调\\n      onError(requestId: string, errorCode: number, errorMessage: string) {\\n        console.error(`onError, requestId: ${requestId} errorCode: ${errorCode} errorMessage: ${errorMessage}`);\\n      }\\n    };\\n    // 设置回调\\n    this.ttsEngine?.setListener(speakListener);\\n  }\\n\\n  /** 开始转换 */\\n  async speak(originalText: string) {\\n    // 设置播报相关参数\\n    let extraParam: Record<string, Object> = {\\n      \\"queueMode\\": 0,\\n      // 语速。可选，支持范围[0.5-2]，不传参时默认为1。\\n      \\"speed\\": 1,\\n      // 音量。 可选，支持范围[0-2]，不传参时默认为1\\n      \\"volume\\": 2,\\n      // 音调。\\n      // 可选，支持范围[0.5-2]，不传参时默认为1\\n      \\"pitch\\": 1,\\n      // 语境，播放阿拉伯数字用的语种。 可选，当前仅支持“zh-CN”中文，不传参时默认“zh-CN”。\\n      \\"languageContext\\": \'zh-CN\',\\n      // 音频类型，当前仅支持“pcm”\\n      \\"audioType\\": \\"pcm\\",\\n      //  通道。 可选，参数范围0-16，整数类型，可参考音频流使用来选择适合自己的音频场景。  不传参时默认为3，语音助手通道\\n      \\"soundChannel\\": 3,\\n      // 合成类型。 可选，不传参时默认为1。 0：仅合成不播报，返回音频流。 1：合成与播报不返回音频流。\\n      \\"playType\\": 1\\n    };\\n    let speakParams: textToSpeech.SpeakParams = {\\n      requestId: this.requestId, // requestId在同一实例内仅能用一次，请勿重复设置\\n      extraParams: extraParam\\n    };\\n    // 调用播报方法\\n    this.ttsEngine?.speak(originalText, speakParams);\\n  }\\n\\n  /** 停止转换 */\\n  async stop() {\\n    this.ttsEngine?.stop()\\n  }\\n}\\n\\nexport default TextToSpeechManager\\n```\\n\\n## 页面中使用\\n\\n`Index.ets`\\n\\n![image-20240829175251444](%E4%B8%89%E6%96%87%E5%B8%A6%E4%BD%A0%E8%BD%BB%E6%9D%BE%E4%B8%8A%E6%89%8B%E9%B8%BF%E8%92%99%E7%9A%84AI%E8%AF%AD%E9%9F%B303-%E6%96%87%E6%9C%AC%E5%90%88%E6%88%90%E5%A3%B0%E9%9F%B3.assets/image-20240829175251444.png)\\n\\n```typescript\\nimport { PermissionManager } from \'../utils/permissionMananger\'\\nimport { Permissions } from \'@kit.AbilityKit\'\\nimport SpeechRecognizerManager from \'../utils/SpeechRecognizerManager\'\\nimport { AudioCapturerManager } from \'../utils/AudioCapturerManager\'\\nimport TextToSpeechManager from \'../utils/TextToSpeechManager\'\\n\\n@Entry\\n@Component\\nstruct Index {\\n  @State\\n  text: string = \\"\\"\\n  fileName: string = \\"\\"\\n  // 1 申请权限\\n  fn1 = async () => {\\n    // 准备好需要申请的权限 麦克风权限\\n    const permissions: Permissions[] = [\\"ohos.permission.MICROPHONE\\"]\\n    // 检查是否拥有权限\\n    const isPermission = await PermissionManager.checkPermission(permissions)\\n    if (!isPermission) {\\n      //   如果没权限，就主动申请\\n      PermissionManager.requestPermission(permissions)\\n    }\\n  }\\n  // 2 实时语音识别\\n  fn2 = () => {\\n    SpeechRecognizerManager.init(res => {\\n      console.log(\\"实时语音识别\\", JSON.stringify(res))\\n      this.text = res.result\\n    })\\n  }\\n  // 3 开始录音\\n  fn3 = () => {\\n    this.fileName = Date.now().toString()\\n    AudioCapturerManager.startRecord(this.fileName)\\n  }\\n  // 4 接收录音\\n  fn4 = () => {\\n    AudioCapturerManager.stopRecord()\\n  }\\n  // 5 声音文件转换文本\\n  fn5 = () => {\\n    SpeechRecognizerManager.init2(res => {\\n      this.text = res.result\\n      console.log(\\"声音文件转换文本\\", JSON.stringify(res))\\n    }, this.fileName)\\n  }\\n  // 6 文本合成声音\\n  fn6 = async () => {\\n    const tts = new TextToSpeechManager()\\n    await tts.createEngine()\\n    tts.setListener((res) => {\\n      console.log(\\"res\\", JSON.stringify(res))\\n    })\\n    tts.speak(\\"我送你离开 千里之外\\")\\n  }\\n\\n  build() {\\n    Column({ space: 10 }) {\\n      Text(this.text)\\n\\n      Button(\\"申请权限\\")\\n        .onClick(this.fn1)\\n      Button(\\"实时语音识别\\")\\n        .onClick(this.fn2)\\n\\n      Button(\\"开始录音\\")\\n        .onClick(this.fn3)\\n      Button(\\"结束录音\\")\\n        .onClick(this.fn4)\\n\\n      Button(\\"声音文件转换文本\\")\\n        .onClick(this.fn5)\\n      Button(\\"文本合成声音\\")\\n        .onClick(this.fn6)\\n\\n    }\\n    .width(\\"100%\\")\\n    .height(\\"100%\\")\\n    .justifyContent(FlexAlign.Center)\\n  }\\n}\\n```\\n\\n## 总结\\n\\nHarmonyOS NEXT 提供的AI 文本合并语音功能，可以将一段不超过10000字符的文本合成为语音并进行播报\\n\\n使用的步骤为3步\\n\\n1. 创建文本合成语音引擎\\n2. 设置监听回调\\n3. 开始合成"}'),r={name:"鸿蒙开发技巧/三文带你轻松上手鸿蒙的AI语音/三文带你轻松上手鸿蒙的AI语音03-文本合成声音/03-文本合成声音.md"};function E(g,s,d,y,F,c){return n(),p("div",null,[...s[0]||(s[0]=[l("",32)])])}const u=a(r,[["render",E]]);export{b as __pageData,u as default};
